insert into public.legal_document_versions(slug,version,status,sha256,document) values ('terms','2026-10-03.3','published','73153b3f9402d65e8baeccd9da099de6293807cf019cddd9dc74932ad5e4ed61','{"slug":"terms","version":"2026-10-03.3","status":"published","title":"Vilkår for EmbedBot","notice":"Disse vilkår gælder ved virksomhedens dokumenterede accept af denne version. Tidligere aftaleversioner og acceptregistreringer bevares.","sections":[{"title":"1. Aftalen","text":"Disse vilkår gælder for virksomhedens brug af EmbedBot, herunder dashboard, chatbot-widget, support, gratis prøveadgang og betalte abonnementer. Aftaleparten er Axel Bødker Frederiksen, som driver EmbedBot. Kontakt: axel@embedbot.dk, telefon +45 91 55 12 50."},{"title":"2. Tjenesten","text":"EmbedBot leverer en AI-baseret chatbot, som kan bruge virksomhedens egne oplysninger og websiteindhold til at besvare besøgendes spørgsmål. Funktioner, kapacitet og inkluderede AI-svar afhænger af den valgte plan. Vi kan foretage rimelige produktændringer, når tjenestens væsentlige funktion ikke forringes væsentligt."},{"title":"3. Gratis prøveadgang","text":"Prøveperioden tilbydes som 14 dage uden betalingskort og bliver ikke automatisk til et betalt abonnement. Adgangen afsluttes kun automatisk, hvis EmbedBot og virksomheden har aftalt en slutdato, eksempelvis i en mail. Uden aftalt slutdato fortsætter prøveadgangen, og det videre forløb aftales med virksomheden. Betaling kræver et aktivt køb. Betalte abonnementer fornyes månedligt, indtil de opsiges."},{"title":"4. Pris, betaling og fornyelse","text":"Aktuelle priser og plangrænser fremgår af prissiden . Priser er i danske kroner pr. måned og eksklusive moms, medmindre andet er angivet. Betaling håndteres af Stripe. Et betalt abonnement fornyes automatisk månedligt, indtil det opsiges. Den valgte pris, betalingsperiode og fornyelse vises før betaling. Virksomheden kan opsige i dashboardet; opsigelsen gælder ved udgangen af den allerede betalte periode. Se betalings- og refusionspolitikken ."},{"title":"5. Konto og adgang","text":"Virksomheden skal give korrekte oplysninger, beskytte loginoplysninger og straks kontakte os ved mistanke om misbrug. Virksomheden er ansvarlig for handlinger foretaget fra dens konto, medmindre de skyldes forhold, som EmbedBot er ansvarlig for."},{"title":"6. Virksomhedens indhold og instruktioner","text":"Virksomheden beholder sine rettigheder til indhold, som den leverer. Virksomheden giver EmbedBot en begrænset ret til at behandle indholdet for at levere, sikre og supportere tjenesten. Virksomheden er ansvarlig for, at den har ret til at bruge og dele indholdet, og for at produkt-, pris-, leverings-, retur-, garanti- og kontaktoplysninger er korrekte. Virksomheden skal gennemgå væsentlige chatbot-svar og må ikke instruere chatbotten i at vildlede kunder eller overtræde lovgivning."},{"title":"7. Personoplysninger","text":"Når EmbedBot behandler virksomhedens besøgendes oplysninger efter virksomhedens instruktioner, er virksomheden normalt dataansvarlig og EmbedBot databehandler. Virksomheden skal give de nødvendige oplysninger til sine besøgende, vælge et lovligt behandlingsgrundlag og undgå at indsamle flere oplysninger end nødvendigt. En databehandleraftale skal være indgået, før EmbedBot bruges til at behandle besøgendes personoplysninger på virksomhedens vegne. Se privatlivspolitikken og cookiepolitikken ."},{"title":"8. Børn og følsomme oplysninger","text":"Tjenesten er ikke målrettet børn. Virksomheden må ikke målrette chatbotten mod børn eller indsamle børns oplysninger på grundlag af samtykke uden selv at sikre et gyldigt alders- og forældresamtykkeforløb. Chatbotten bør ikke bruges til CPR-numre, helbredsoplysninger, betalingskortoplysninger eller andre følsomme oplysninger, medmindre det er særskilt aftalt og lovligt."},{"title":"9. Acceptabel brug","text":"EmbedBot må ikke bruges til ulovligt indhold, spam, phishing, chikane, malware, krænkelse af tredjemands rettigheder, omgåelse af sikkerhed eller belastning af tjenesten ud over normal brug. Sikkerhedsforanstaltninger må ikke testes uden skriftlig tilladelse."},{"title":"10. AI-begrænsninger","text":"AI-genererede svar kan være ufuldstændige eller forkerte. EmbedBot bruger tekniske og instruktionelle sikkerhedsforanstaltninger, men kan ikke garantere, at alle fejl, manipulationer eller prompt-injection-forsøg bliver opdaget. Chatbotten må ikke være eneste grundlag for juridisk, medicinsk, finansiel eller anden højrisikorådgivning."},{"title":"11. Tredjeparter","text":"Tjenesten anvender blandt andet OpenAI, Supabase, Stripe, Resend, Vercel og Plausible. Driftsforstyrrelser eller ændringer hos disse leverandører kan påvirke tjenesten. Vi vælger og administrerer leverandører med rimelig omhu, men kan ikke kontrollere deres tjenester fuldt ud."},{"title":"12. Tilgængelighed, support og sikkerhed","text":"Vi tilstræber stabil drift og rimelig support, men lover ikke uafbrudt eller fejlfri adgang. Planlagt vedligeholdelse, sikkerhedshændelser eller forhold uden for vores kontrol kan give afbrydelser. Vi anvender rimelige tekniske og organisatoriske sikkerhedsforanstaltninger."},{"title":"13. Suspension og ophør","text":"Vi kan suspendere adgang ved manglende betaling, væsentlig misligholdelse, sikkerhedsrisiko eller ulovlig brug. Hvor det er rimeligt, giver vi mulighed for at rette forholdet først. Ved ophør bør virksomheden eksportere nødvendige data. Sletning og opbevaring følger privatlivspolitikken og gældende lov."},{"title":"14. Ansvar","text":"Parterne er ansvarlige efter dansk rets almindelige regler med de begrænsninger, der lovligt kan aftales mellem erhvervsdrivende. EmbedBot er ikke ansvarlig for indirekte tab, driftstab, tabt avance eller tab, der skyldes virksomhedens urigtige indhold eller brug af AI-svar uden relevant kontrol. EmbedBots samlede ansvar er, i det omfang loven tillader det, begrænset til det beløb, virksomheden har betalt for tjenesten i de seneste 12 måneder. Begrænsningen gælder ikke ved forsæt, grov uagtsomhed eller ansvar, som ikke lovligt kan begrænses."},{"title":"15. Ændringer","text":"Væsentlige ændringer til priser eller vilkår varsles normalt mindst 30 dage før ikrafttræden. Hvis en ændring har væsentlig negativ betydning, kan virksomheden opsige abonnementet inden ændringen træder i kraft."},{"title":"16. Lovvalg og kontakt","text":"Aftalen er underlagt dansk ret. Tvister søges først løst i dialog og kan derefter indbringes for de danske domstole efter de almindelige værnetingsregler. Spørgsmål kan sendes til axel@embedbot.dk eller via support ."}],"suppliers":[{"provider":"Supabase","legalName":"Supabase Pte. Ltd. (Singapore)","service":"Database og Auth","purpose":"Konto, chat, supportsager, videnskilder og integrationer","data":"Konto- og virksomhedsoplysninger, chat, supportsager og krypterede webshopcredentials","location":"Projektets database og Auth er placeret i Frankfurt, Tyskland (eu-central-1). Leverandørens support og underleverandører kan behandle oplysninger uden for EU/EØS; projektregionen er ikke en garanti om udelukkende EU-behandling.","role":"Underdatabehandler for kundens chat- og supportdata; databehandler for EmbedBots egne kontooplysninger.","transfer":"Supabases DPA indeholder EU-standardkontraktbestemmelser (SCC) for relevante tredjelandsoverførsler. Videreoverførsler følger DPA og underdatabehandlerlisten.","scope":"Kundens chatbot og EmbedBots kontoadministration","information":"https://supabase.com/legal/customer-resources/data-processing-addendum","sources":[["Databehandleraftale","https://supabase.com/legal/customer-resources/data-processing-addendum"],["Underdatabehandlere","https://supabase.com/legal/customer-resources/subprocessor-list"],["Region og dataresidens","https://supabase.com/docs/guides/security/gdpr-compliance"]],"evidence":"Projektregion kontrolleret i Supabase; offentlige aftaler og dokumentation gennemgået 3. oktober 2026.","reviewedAt":"2026-10-03"},{"provider":"OpenAI","legalName":"OpenAI Ireland Ltd. for EØS-/schweiziske kunder; OpenAI OpCo, LLC for øvrige kunder efter standardaftalen.","service":"AI API","purpose":"Chatgenerering, klassifikation og embeddings af videnskilder","data":"Aktuelle spørgsmål, nødvendig samtalehistorik og relevante videnskilder. Private ordreformularer og ordresvar håndteres særskilt.","location":"Den aktuelle integration bruger det almindelige API uden et konfigureret europæisk API-endpoint. Der gives ingen garanti om EU-behandling. Behandling kan ske i USA og hos leverandørens underdatabehandlere.","role":"Underdatabehandler for oplysninger behandlet på webshopkundens vegne.","transfer":"OpenAIs DPA beskriver SCC eller en gældende tilstrækkelighedsafgørelse som grundlag for overførsler af EØS-data til tredjelande.","scope":"Kundens chatbot og videnssøgning","information":"https://openai.com/policies/data-processing-addendum/","sources":[["Databehandleraftale","https://openai.com/policies/data-processing-addendum/"],["Datakontroller og opbevaring","https://developers.openai.com/api/docs/guides/your-data"],["Underdatabehandlere","https://platform.openai.com/subprocessors"]],"evidence":"API-integration og AI Council-datadeling kontrolleret. Tilvalgt deling til modeltræning var slået fra ved kontokontrollen 3. oktober 2026.","reviewedAt":"2026-10-03"},{"provider":"Vercel","legalName":"Vercel Inc. (USA)","service":"Hosting, serverbehandling, Cron, Web Analytics og Speed Insights","purpose":"Levering af hjemmeside og API, driftsjobs samt samtykkebaseret besøgs- og ydelsesmåling","data":"HTTP-trafik, serverbehandlede chatbot- og kontoforespørgsler samt tekniske drifts- og målingsoplysninger","location":"Vercels offentlige DPA angiver primær behandling i USA og mulig behandling i andre lande hos Vercel og underdatabehandlere. Der loves ikke udelukkende EU-hosting.","role":"Hosting behandler oplysninger på EmbedBots og kundens vegne. Den offentlige databehandleraftale omfatter Pro/Enterprise; den aktuelle Hobby-plan har ikke dokumenteret dækning under denne aftale.","transfer":"Vercels DPA beskriver SCC for relevante overførsler. Dette kan ikke registreres som EmbedBots aftalegrundlag på Hobby uden en særskilt dækkende aftale.","scope":"Kundens chatbot/API og EmbedBots eget website","information":"https://vercel.com/legal/dpa","sources":[["Databehandleraftale","https://vercel.com/legal/dpa"],["Hobby-planens anvendelse","https://vercel.com/docs/plans/hobby"],["Underdatabehandlere","https://security.vercel.com/"]],"evidence":"Hobby-plan bekræftet af kontoejeren 3. oktober 2026. Kommerciel kundedrift kræver passende hostingplan og aftaledækning.","reviewedAt":"2026-10-03"},{"provider":"Resend","legalName":"Plus Five Five, Inc. (Resend, USA)","service":"Transaktionsmail","purpose":"Aktivering, supportnotifikationer og verifikationskoder","data":"Modtagermailadresse, relevant mailindhold og leveringsoplysninger","location":"Mailindhold, leveringslogs og kontooplysninger lagres i USA. EmbedBots afsenderregion er Irland (eu-west-1); dette ændrer ikke lagringsstedet.","role":"Underdatabehandler for kundens supportnotifikationer; databehandler for EmbedBots egne transaktionsmails.","transfer":"Resends DPA indeholder SCC, herunder modul 3 ved underdatabehandling. Denne oversigt bygger ikke på en selvstændig bekræftelse af DPF-certificering.","scope":"Kundens supportfunktioner og EmbedBots kontomails","information":"https://resend.com/legal/dpa","sources":[["Databehandleraftale","https://resend.com/legal/dpa"],["Behandlingssteder og opbevaring","https://resend.com/security/gdpr"],["Underdatabehandlere","https://resend.com/legal/subprocessors"]],"evidence":"Afsenderdomæne og Irland-region kontrolleret. Enforced TLS er aktiveret for embedbot.dk; offentlige kilder gennemgået 3. oktober 2026.","reviewedAt":"2026-10-03"},{"provider":"Stripe","legalName":"Stripe Payments Europe, Limited for danske konti efter standardaftalen; Stripe Technology Europe, Limited kan indgå for relevante finansielle tjenester.","service":"Betalte EmbedBot-abonnementer","purpose":"Betaling, abonnement, fakturering og opsigelse","data":"Kunde- og virksomhedsreference, mailadresse, betalingsstatus og betalingsoplysninger hos Stripe. EmbedBot gemmer ikke fulde kortnumre.","location":"Behandling hos Stripe i EU/EØS og internationalt, herunder overførsel til Stripe, LLC i USA og relevante koncernselskaber og underdatabehandlere.","role":"Databehandler for visse tjenester og selvstændig dataansvarlig for bl.a. svindelforebyggelse, myndighedskrav og egne driftsformål. Ikke underdatabehandler for kundens chatbotindhold.","transfer":"Stripes Data Transfers Addendum regulerer relevante tredjelandsoverførsler, herunder SCC og øvrige anvendelige overførselsmekanismer.","scope":"EmbedBots egen abonnements- og betalingsadministration","information":"https://stripe.com/legal/dpa","sources":[["Danske tjenestevilkår","https://stripe.com/dk/legal/ssa"],["Databehandleraftale","https://stripe.com/legal/dpa"],["Overførselsbilag","https://stripe.com/legal/dta"]],"evidence":"Betalingsintegration og leverandørens offentlige danske standardvilkår gennemgået 3. oktober 2026.","reviewedAt":"2026-10-03"},{"provider":"Plausible","legalName":"Plausible Insights OÜ (Estland)","service":"Webanalyse","purpose":"Samtykkebaseret besøgsstatistik på EmbedBots eget website","data":"Sidebesøg og tekniske besøgsoplysninger. URL-parametre og referrer fjernes fra EmbedBots Plausible-måling.","location":"Websitebesøgsdata behandles i EU. Plausible angiver Hetzner (Tyskland), Bunny (Slovenien) og UpCloud (Finland) som underdatabehandlere for disse data.","role":"Databehandler for EmbedBots besøgsstatistik; selvstændig dataansvarlig for egen kundekonto, betaling og support. Ikke underdatabehandler for webshopkundens chatbot.","transfer":"Plausible angiver, at websitebesøgsdata forbliver i EU. Leverandørens behandling af EmbedBots egne kontooplysninger er særskilt og kan omfatte tredjelandsleverandører.","scope":"EmbedBots eget website efter analysesamtykke","information":"https://plausible.io/privacy","sources":[["Juridisk enhed","https://plausible.io/imprint"],["Roller og behandlingssteder","https://plausible.io/privacy"],["Databehandleraftale","https://plausible.io/dpa"]],"evidence":"Analyseindlæsning og leverandørens offentlige dokumentation gennemgået 3. oktober 2026.","reviewedAt":"2026-10-03"}],"sha256":"73153b3f9402d65e8baeccd9da099de6293807cf019cddd9dc74932ad5e4ed61"}'::jsonb);
insert into public.legal_document_versions(slug,version,status,sha256,document) values ('dpa','2026-10-03.2','draft','53dfc2e1bc2037df8e36a520aba61cc33b3f84ceb8df8a3ea31ba0a6c3e0fb67','{"slug":"dpa","version":"2026-10-03.2","status":"draft","title":"Databehandleraftale — EmbedBot 1.0","notice":"Kundeaccept er endnu ikke åben: EmbedBot bruger Vercel Hobby, som ikke er omfattet af Vercels offentlige databehandleraftale for Pro/Enterprise. Før aftaleindgåelse skal hostingens aftaledækning, konkrete overførselsbilag og kundens juridiske identitet være dokumenteret. Denne læseversion registrerer ingen accept.","content":"# Databehandleraftale — EmbedBot 1.0\n\nVersion: 2026-10-03.2 · Dato: 3. oktober 2026\n\n## 1. Parterne og aftalens anvendelse\n\nDenne databehandleraftale indgås mellem den virksomhed eller person, der er identificeret som kunde i den tilhørende tjenesteaftale og aftaleregistrering (herefter **Kunden**), og:\n\n**Axel Bødker Frederiksen, som driver EmbedBot**  \nE-mail: axel@embedbot.dk · Telefon: +45 91 55 12 50  \n(herefter **Databehandleren**).\n\nKunden er dataansvarlig for de personoplysninger, som Databehandleren behandler på Kundens vegne ved levering af EmbedBot. Kundens juridiske navn, adresse, eventuelle CVR eller anden registrering samt autoriserede kontakt og sikkerhedskontakt skal være registreret ved aftaleindgåelsen. En kontaktpersons navn erstatter ikke identifikation af den juridiske aftalepart.\n\nAftalen og bilag A–D fastlægger behandlingen i henhold til databeskyttelsesforordningens artikel 28. Aftalen har forrang for tjenesteaftalen ved modstrid om behandling af personoplysninger på Kundens vegne.\n\n## 2. Genstand og varighed\n\nDatabehandleren leverer website-chatbot, dashboard, indlæsning af videnskilder og de support- og webshopfunktioner, Kunden har valgt. Behandlingens indhold og formål fremgår af bilag A og Kundens dokumenterede instrukser.\n\nAftalen gælder fra Kundens accept og så længe Databehandleren eller dennes underdatabehandlere behandler personoplysninger på Kundens vegne. En gratis prøveperiode er omfattet på samme måde som betalt brug. Udløb eller opsigelse af tjenesten bringer ikke databeskyttelsesforpligtelserne til ophør, mens oplysninger fortsat behandles.\n\n## 3. Kundens ansvar\n\nKunden bestemmer formålene med behandlingen og sikrer et gyldigt behandlingsgrundlag, nødvendige oplysninger til de registrerede og lovligheden af de instrukser og oplysninger, der gives til Databehandleren.\n\nKunden skal begrænse oplysningerne til det nødvendige, vælge passende opbevaringsperioder og sikre, at egne brugere kun har den adgang, de har behov for. Kunden skal oplyse Databehandleren om særlige risici, der har betydning for sikkerheden eller den aftalte behandling.\n\nKunden afgør anmodninger fra registrerede og behovet for anmeldelse, underretning, konsekvensanalyse og forudgående høring. Dette begrænser ikke Databehandlerens selvstændige forpligtelser efter aftalen og gældende ret.\n\n## 4. Dokumenterede instrukser\n\nDatabehandleren må kun behandle personoplysninger efter Kundens dokumenterede instrukser, herunder ved overførsler til tredjelande, medmindre EU-ret eller medlemsstatens nationale ret kræver anden behandling. Ved et sådant lovkrav underretter Databehandleren Kunden før behandlingen, medmindre lovgivningen forbyder underretningen af hensyn til vigtige samfundsinteresser.\n\nInstrukserne består af denne aftale, dens bilag og Kundens autoriserede valg af funktioner og indstillinger. Supplerende instrukser gives skriftligt til axel@embedbot.dk eller gennem en verificeret kontokanal. Databehandleren registrerer instrukserne og afklarer uklarheder eller modstridende krav med Kunden før udførelse.\n\nDatabehandleren underretter straks Kunden, hvis en instruks efter Databehandlerens vurdering strider mod databeskyttelsesreglerne. Den berørte behandling sættes i bero under afklaringen, i det omfang dette kan ske uden at kompromittere datasikkerheden.\n\nDatabehandleren må ikke anvende Kundens personoplysninger til egne salgsformål eller til træning af egne generelle AI-modeller eller aktivere leverandørdeling til generel modeltræning af disse oplysninger.\n\n## 5. Fortrolighed og adgang\n\nDatabehandleren sikrer, at kun autoriserede personer med et nødvendigt arbejdsbetinget behov har adgang til personoplysningerne. Personerne skal være underlagt en passende lovbestemt eller aftalt fortrolighedsforpligtelse og instrueret i sikker behandling.\n\nAdgang skal tildeles efter princippet om mindst mulig adgang, gennemgås regelmæssigt og fjernes, når behovet ophører. Tilsvarende krav skal sikres gennem aftaler med underdatabehandlere.\n\n## 6. Behandlingssikkerhed\n\nDatabehandleren gennemfører passende tekniske og organisatoriske foranstaltninger efter artikel 32 under hensyn til behandlingens karakter, omfang, sammenhæng, formål og risiko for de registrerede. Foranstaltningerne er beskrevet i bilag B.\n\nDatabehandleren skal kunne opretholde fortrolighed, integritet, tilgængelighed og robusthed og kunne genoprette adgang til oplysningerne rettidigt efter en fysisk eller teknisk hændelse. Sikkerhedsforanstaltningernes effektivitet skal regelmæssigt kontrolleres og vurderes.\n\nForanstaltningerne kan tilpasses den tekniske udvikling og risikoen. Ændringer må ikke reducere det beskyttelsesniveau, aftalen kræver.\n\n## 7. Underdatabehandlere\n\nKunden giver ved aftaleindgåelsen generel skriftlig godkendelse til de underdatabehandlere, som er identificeret og omfattet af det aftalte bilag C. Godkendelsen omfatter kun de beskrevne behandlingsaktiviteter og behandlingssteder.\n\nDatabehandleren varsler tilføjelse eller udskiftning mindst 30 kalenderdage før ændringen til Kundens registrerede kontaktmail. Varslet skal give Kunden tilstrækkelig information til at vurdere ændringen og mulighed for en begrundet indsigelse inden ændringen.\n\nVed indsigelse søger parterne en lovlig løsning. Den berørte nye behandling påbegyndes ikke for Kunden, mens indsigelsen er uafklaret. Kan der ikke findes en lovlig løsning, kan den berørte del af tjenesten bringes til ophør med tilbagelevering og sletning efter punkt 13.\n\nDatabehandleren indgår skriftlige aftaler med underdatabehandlerne, som pålægger dem de samme relevante databeskyttelsesforpligtelser som denne aftale, og sikrer tilstrækkelige garantier for passende sikkerhed. Databehandleren forbliver fuldt ansvarlig over for Kunden for underdatabehandlernes opfyldelse af disse forpligtelser.\n\nDatabehandleren stiller efter anmodning relevante aftaleoplysninger til rådighed for Kunden. Irrelevante forretningsoplysninger kan beskyttes, uden at det forhindrer kontrollen af databeskyttelsesforpligtelserne.\n\n## 8. Internationale overførsler\n\nOverførsel til eller adgang fra et land uden for EU/EØS må kun ske efter Kundens dokumenterede instruks og i overensstemmelse med databeskyttelsesforordningens kapitel V.\n\nFør overførslen skal Databehandleren dokumentere modtager, land, formål og gældende overførselsgrundlag samt nødvendige vurderinger og supplerende foranstaltninger. Oplysningerne skal indgå i bilag C eller en skriftlig supplering, som Kunden godkender før den berørte behandling. En generel leverandørliste giver ikke i sig selv instruks til ubeskrevne overførsler.\n\nDatabehandleren må ikke love udelukkende EU/EØS-behandling alene på baggrund af en valgt databaseregion. Supportadgang, AI-behandling og videreoverførsler skal indgå i vurderingen. Hvis et grundlag bortfalder, skal den berørte overførsel standses, indtil et lovligt grundlag er etableret.\n\n## 9. Registreredes rettigheder\n\nDatabehandleren bistår Kunden med passende tekniske og organisatoriske foranstaltninger til at besvare anmodninger om de registreredes rettigheder, under hensyn til behandlingens karakter.\n\nDatabehandleren videresender uden unødig forsinkelse anmodninger vedrørende Kundens behandling til Kundens autoriserede kontakt. Databehandleren afgør ikke anmodningen uden Kundens instruks, medmindre gældende ret kræver det.\n\nKunden kontrollerer anmoderens identitet og ret til oplysningerne før opslag, udlevering eller sletning. En e-mailadresse i en chat er ikke identitetsbevis. Databehandleren bistår med søgning, sikker eksport, rettelse, begrænsning og sletning. Manglende søgeresultater eller tekniske begrænsninger meddeles Kunden, så historiske kopier, aliaser og andre relevante oplysninger kan gennemgås.\n\n## 10. Brud på persondatasikkerheden\n\nDatabehandleren underretter Kunden uden unødig forsinkelse efter at være blevet bekendt med et brud på persondatasikkerheden vedrørende Kundens oplysninger.\n\nUnderretningen skal, i det omfang oplysningerne er tilgængelige, beskrive bruddets karakter, kategorier og omtrentligt antal registrerede og berørte dataposter, sandsynlige konsekvenser, relevante kontaktoplysninger samt trufne eller foreslåede afværgeforanstaltninger.\n\nManglende oplysninger gives løbende uden unødig yderligere forsinkelse. Underretning afventer ikke en afsluttet undersøgelse. Databehandleren bistår Kunden med undersøgelse, afværgning og nødvendig dokumentation til anmeldelse og underretning.\n\n## 11. Assistance ved sikkerhed og vurderinger\n\nDatabehandleren bistår Kunden med forpligtelserne efter artikel 32–36 under hensyn til behandlingens karakter og de oplysninger, der er tilgængelige for Databehandleren.\n\nAssistance omfatter relevante oplysninger om behandlingen, sikkerhedsforanstaltninger, modtagere, behandlingssteder og risici samt bistand ved konsekvensanalyse og eventuel forudgående høring. Praktiske rammer aftales uden at begrænse den lovpligtige assistance.\n\n## 12. Opbevaring\n\nOplysninger opbevares efter perioderne i bilag D og Kundens dokumenterede instrukser. Afvigelser skal være begrundede og registreres. En ændring gælder fremadrettet efter den aftalte instruks og genskaber ikke allerede slettede oplysninger.\n\nKopierede samtaleudsnit må ikke bevare oplysninger ud over den relevante kortere slettefrist. Databehandleren sikrer, at sletning også omfatter tilknyttede kopier og relevante underdatabehandlere efter den aftalte sletteprocedure. Lovpligtige undtagelser skal afgrænses og dokumenteres.\n\n## 13. Returnering og sletning ved ophør\n\nVed tjenestens ophør tilbageleverer eller sletter Databehandleren efter Kundens valg de personoplysninger, der behandles på Kundens vegne, og sletter eksisterende kopier, medmindre EU-ret eller medlemsstatens nationale ret kræver fortsat opbevaring.\n\nKunden kan vælge eksport før sletning. Afslutningsperioden er højst 30 kalenderdage fra ophørsdatoen, og Kunden kan instruere tidligere sletning. Behandling i perioden begrænses til nødvendig sikker opbevaring, tilbagelevering og sletning; almindelig chatbotbehandling og integrationer skal ophøre. Kortere løbende slettefrister fortsætter uændret.\n\nDatabehandlerens egne backupkopier udfases senest efter den aftalte backupfrist på 30 dage fra backupkopiens oprettelse. De må ikke bruges til almindelig behandling efter sletteinstruksen. Ved gendannelse skal tidligere sletninger genudføres før normal drift genoptages.\n\nLovpligtig opbevaring begrænses til det nødvendige, og Kunden orienteres om omfang, grundlag og periode, medmindre lovgivningen forbyder orienteringen. Underleverandørers sletteforhold skal håndteres efter punkt 7 og bilag C; en leverandørs generelle kontoophørsfrist er ikke en forlængelse af Kundens aftalte slettefrist.\n\nDatabehandleren dokumenterer og bekræfter afslutningen over for Kunden med dato, omfang og eventuelle lovpligtige undtagelser. Kundens egne downloads, indbakker og oplysninger i Kundens webshop håndteres af Kunden.\n\n## 14. Dokumentation og kontrol\n\nDatabehandleren stiller alle nødvendige oplysninger til rådighed for at dokumentere opfyldelsen af artikel 28 og giver mulighed for og bidrager til revisioner og inspektioner foretaget af Kunden eller en revisor, som Kunden har bemyndiget.\n\nDokumentationsgennemgang kan anvendes som første trin, når den er tilstrækkelig. Nødvendig revision og inspektion tilrettelægges med sikker adgang og beskyttelse af andre kunders oplysninger. Fortrolighed eller almindelige varslingsregler må ikke forhindre en effektiv kontrol, herunder ved sikkerhedsbrud, myndighedskrav eller konkret mistanke om manglende overholdelse.\n\n## 15. Kontakt og samarbejde\n\nDatabehandlerens kontakt for instrukser, rettighedsanmodninger og sikkerhedshændelser er Axel Bødker Frederiksen, axel@embedbot.dk, +45 91 55 12 50.\n\nKunden holder sine autoriserede kontaktoplysninger ajour. Databehandleren skal organisere modtagelse og håndtering af henvendelser, så aftalens forpligtelser også kan opfyldes ved fravær. Der aftales ikke en særskilt døgnbemandet supportordning eller fast reaktionstid; kravet om underretning uden unødig forsinkelse gælder fortsat.\n\n## 16. Rolleafgrænsning\n\nAftalen omfatter behandling på Kundens vegne. Behandling til Databehandlerens egne formål, eksempelvis administration af EmbedBot-abonnementer, fakturering og egne websitebesøg, beskrives særskilt i EmbedBots privatlivspolitik og omfattes ikke automatisk af Kundens instruks.\n\nDenne afgrænsning giver ikke Databehandleren ret til at genbruge Kundens chat-, lead- eller supportoplysninger til egne formål.\n\n## 17. Aftaleindgåelse og ændringer\n\nAftalen indgås ved dokumenteret accept af den publicerede version af en person med ret til at handle på Kundens vegne eller ved parternes skriftlige underskrift. Kundens identitet, aftaleversion, bilag og accepttidspunkt skal fremgå af aftaleregistreringen.\n\nTidligere kunders brug udgør ikke accept af en ny version. Ændringer dokumenteres i en ny version, og tidligere aftaleversioner bevares. Aftalen må ikke fortolkes, så den begrænser rettigheder eller forpligtelser efter databeskyttelsesreglerne.\n\n# Bilag A — behandling og instrukser\n\n| Område | Aftalt behandling |\n| --- | --- |\n| Formål | Besvarelse af spørgsmål, kundeservice, videnssøgning og de support-/webshopfunktioner, Kunden har aktiveret. Leadopfølgning sker alene til Kundens dokumenterede lovlige formål. |\n| Behandlingshandlinger | Modtagelse, lagring, organisering, søgning, AI-generering, visning, eksport, videresendelse efter instruks og sletning. |\n| Registrerede | Kundens websitebesøgende, kunder, medarbejdere og andre personer, hvis oplysninger indgår i Kundens lovligt indlæste materiale eller henvendelser. |\n| Oplysninger | Chatindhold, frivillige kontaktoplysninger, tidspunkt, sideadresse, supportbeskrivelse og relevante samtaleudsnit. Videnskilder kan indeholde personoplysninger. Ved aktiv webshopintegration desuden ordre-reference, e-mail og begrænsede ordre-/statusoplysninger. |\n| AI | Relevante videnskilder, den aktuelle chat og nødvendig historik behandles hos den aftalte AI-leverandør til svar og embeddings. Personoplysninger, som indtastes i fri chattekst, kan indgå. Private ordreformularer og ordresvar følger særskilt verifikation. |\n| Leads | Dashboardet kan vise kontakt-e-mails fra chats med beskedudsnit, sideadresse og tidspunkt samt eksportere dem. Funktionen registrerer ikke marketingtilladelse. En kontakt-e-mail er ikke i sig selv samtykke til elektronisk markedsføring; Kunden sikrer nødvendig tilladelse eller gældende undtagelse. |\n| Særlige kategorier | Tjenesten er ikke indrettet til tilsigtet behandling af følsomme oplysninger eller oplysninger om strafbare forhold. Sådan planlagt behandling kræver særskilt skriftlig aftale, risikovurdering og passende foranstaltninger før påbegyndelse. Utilsigtet indtastning håndteres efter Kundens instruks. |\n| Kundevalgte modtagere | Kundens tilsluttede Shopify/WooCommerce-webshop og registrerede supportindbakke ved de valgte funktioner. Kundens egne eksporter og videresendelser håndteres under Kundens ansvar. |\n\nKundens konkrete funktioner, formål med leadopfølgning og eventuelle afvigende instrukser skal dokumenteres ved aftaleindgåelsen. Nye formål kræver en supplerende dokumenteret instruks.\n\n# Bilag B — sikkerhedsforanstaltninger\n\nDatabehandleren skal opretholde følgende foranstaltninger i den behandling, aftalen omfatter:\n\n- Serverkontrolleret login og ejerskab samt adskillelse af kundernes data i API''er og databaseadgang.\n- Begrænset adgang til private integrations- og compliancefunktioner; autorisation og passende flerfaktorbeskyttelse for privilegeret adgang.\n- Krypteret transport og beskyttelse af database og backup efter risikoen. Webshopcredentials og private ordrelokatorer beskyttes med autentificeret kryptering; nøgler holdes adskilt fra almindelige kundedata og udelades fra eksport.\n- Tidsbegrænset og sessionsbundet verifikation ved private ordreopslag, begrænsning af gentagne forsøg og kontrol af anmodningers oprindelse ved private ændringer.\n- Eksport af afgrænsede kundedata uden adgangskoder, API-nøgler, tokens eller integrationscredentials. Identitetskontrol og særskilt bekræftelse før besøgsdatasletning.\n- Begrænsede audit- og driftsoplysninger til dokumentation af handlinger og jobstatus uden unødvendigt chatindhold eller hemmeligheder.\n- Dokumenteret oprydning efter aftalte perioder, kontrol af udfald og håndtering af fejlede jobs.\n- Krypteret backup, beskyttet nøgleforvaring, rotation efter bilag D og regelmæssig kontrol af gendannelse, herunder håndtering af tidligere sletninger.\n- Vedligeholdelse, adgangsreview, fortrolighed, relevant oplæring og dokumenteret håndtering af sikkerhedshændelser og rettighedsanmodninger.\n\nForanstaltningerne beskriver Databehandlerens kontraktlige minimumsforpligtelser; de udgør ikke en certificering eller garanti for, at sikkerhedshændelser aldrig kan indtræffe.\n\n# Bilag C — underdatabehandlere og behandlingssteder\n\nFølgende leverandører indgår i tjenestens leverandørgrundlag. Anvendelse på Kundens vegne forudsætter, at de relevante aftaler og den konkrete overførselsinstruks efter punkt 8 er etableret før behandlingen.\n\n| Leverandør og juridisk enhed | Funktion og oplysninger | Behandlingssted og ramme |\n| --- | --- | --- |\n| Supabase Pte. Ltd. | Database og kontologin; chats, supportsager, videnskilder, virksomhedsoplysninger og krypterede integrationer. | Projektets database og Auth ligger i Frankfurt, Tyskland. Supabases DPA indeholder SCC for relevante tredjelandsoverførsler. Supportadgang og videreoverførsler følger leverandørens DPA og underdatabehandlerliste og skal indgå i den konkrete overførselsvurdering. |\n| OpenAI Ireland Ltd. efter standardaftalen for EØS-kunder | API-svar, klassifikation og embeddings med relevant chat- og kildeindhold. | Det almindelige API anvendes uden en aftalt EU-behandlingsgaranti. OpenAIs DPA beskriver SCC eller en tilstrækkelighedsafgørelse ved relevante EØS-overførsler. Modtagere og supplerende foranstaltninger dokumenteres efter punkt 8. |\n| Plus Five Five, Inc. (Resend) | Transaktionsmail, supportnotifikationer og verifikationskoder ved de aktiverede funktioner. | Maildata lagres i USA; afsenderregionen Irland ændrer ikke lagringsstedet. Resends DPA indeholder SCC-modul 3 ved underdatabehandling. EmbedBots afsenderdomæne bruger Enforced TLS. Modtagerens egen indbakke styres af Kunden. |\n| Vercel Inc. | Hosting, serverbehandling og planlagte driftsjobs. | Vercels offentlige DPA beskriver primær behandling i USA og SCC for relevante overførsler og gælder Pro/Enterprise. EmbedBot bruger Hobby; dækkende kommerciel hosting og databehandleraftale skal etableres før kundeaccept. Den generelle DPA registreres ikke som gældende for Hobby. |\n\nFør Kundens behandling påbegyndes, skal den kundespecifikke supplering identificere følgende for hver relevant overførsel: juridisk modtager, land, behandlingsaktivitet, datakategorier, adgangsform, overførselsgrundlag og nødvendige supplerende foranstaltninger. Manglende supplering giver ingen tilladelse til den ubeskrevne overførsel.\n\nLeverandørers særskilte sikkerheds-, log- og backupkopier skal kortlægges og indgå i den konkrete sletteprocedure. Almindelig OpenAI abuse-monitoring kan indebære opbevaring i op til 30 dage med leverandørens beskrevne undtagelser. Resend beskriver 30 dages mail-/logopbevaring, syv dages backup og en særskilt frist efter lukning af hele leverandørkontoen. Lukning af hele leverandørkontoen er ikke det samme som ophør for én Kunde. Sådanne generelle leverandørvilkår udgør hverken en slettebekræftelse for Kundens oplysninger eller en selvstændig tilladelse til længere opbevaring efter denne aftale.\n\nKundens egen webshop, supportindbakke og eksporter er kundevalgte datakilder og modtagere. Stripe-betaling for EmbedBots abonnementer og analyse af EmbedBots eget website omfattes ikke automatisk af dette underdatabehandlerbilag.\n\n# Bilag D — opbevaring, eksport og ophør\n\n| Oplysninger eller handling | Instruks |\n| --- | --- |\n| Chats og afledte leads i EmbedBot | 30 dage fra samtalens oprettelse, medmindre en begrundet anden periode er dokumenteret. Leads følger samtalens sletning. |\n| Supportsager | 90 dage fra supportsagens oprettelse, medmindre en begrundet anden periode er dokumenteret. |\n| Kopieret chatkontekst | Den relevante kortere chat-/sagsfrist; skal også fjernes ved sletning af den tilknyttede samtale. |\n| Videnskilder og integrationsdata | Så længe de er nødvendige for den aftalte aktive tjeneste; fjernes ved relevant udskiftning, frakobling eller ophør efter instruks. |\n| Midlertidige verifikations- og forbindelsesoplysninger | Efter deres tekniske udløb, når de ikke længere er nødvendige for det afgrænsede sikkerhedsformål. |\n| Databehandlerens egne databasebackups | Højst 30 dage fra den enkelte backupkopis oprettelse; tidligere sletninger respekteres ved gendannelse. |\n| Eksport og sletning ved ophør | Efter Kundens valg, afsluttet senest 30 kalenderdage fra tjenestens ophør eller tidligere efter Kundens instruks. |\n| Kundevalgte kopier | Kundens downloads, indbakker og webshopoplysninger håndteres og slettes af Kunden. |\n\nPerioderne er kontraktlige instrukser og ikke generelle lovbestemte standardfrister. Kunde- eller formålsspecifikke afvigelser registreres med begrundelse og autoriseret instruks. Opbevaring af interne sikkerheds-/auditoplysninger skal afgrænses efter deres eget nødvendige formål; sådanne logs må ikke bruges til at bevare slettet chatindhold eller credentials.\n","blocks":[{"type":"heading","text":"1. Parterne og aftalens anvendelse"},{"type":"paragraph","text":"Denne databehandleraftale indgås mellem den virksomhed eller person, der er identificeret som kunde i den tilhørende tjenesteaftale og aftaleregistrering (herefter **Kunden**), og:"},{"type":"paragraph","text":"**Axel Bødker Frederiksen, som driver EmbedBot**\nE-mail: axel@embedbot.dk · Telefon: +45 91 55 12 50\n(herefter **Databehandleren**)."},{"type":"paragraph","text":"Kunden er dataansvarlig for de personoplysninger, som Databehandleren behandler på Kundens vegne ved levering af EmbedBot. Kundens juridiske navn, adresse, eventuelle CVR eller anden registrering samt autoriserede kontakt og sikkerhedskontakt skal være registreret ved aftaleindgåelsen. En kontaktpersons navn erstatter ikke identifikation af den juridiske aftalepart."},{"type":"paragraph","text":"Aftalen og bilag A–D fastlægger behandlingen i henhold til databeskyttelsesforordningens artikel 28. Aftalen har forrang for tjenesteaftalen ved modstrid om behandling af personoplysninger på Kundens vegne."},{"type":"heading","text":"2. Genstand og varighed"},{"type":"paragraph","text":"Databehandleren leverer website-chatbot, dashboard, indlæsning af videnskilder og de support- og webshopfunktioner, Kunden har valgt. Behandlingens indhold og formål fremgår af bilag A og Kundens dokumenterede instrukser."},{"type":"paragraph","text":"Aftalen gælder fra Kundens accept og så længe Databehandleren eller dennes underdatabehandlere behandler personoplysninger på Kundens vegne. En gratis prøveperiode er omfattet på samme måde som betalt brug. Udløb eller opsigelse af tjenesten bringer ikke databeskyttelsesforpligtelserne til ophør, mens oplysninger fortsat behandles."},{"type":"heading","text":"3. Kundens ansvar"},{"type":"paragraph","text":"Kunden bestemmer formålene med behandlingen og sikrer et gyldigt behandlingsgrundlag, nødvendige oplysninger til de registrerede og lovligheden af de instrukser og oplysninger, der gives til Databehandleren."},{"type":"paragraph","text":"Kunden skal begrænse oplysningerne til det nødvendige, vælge passende opbevaringsperioder og sikre, at egne brugere kun har den adgang, de har behov for. Kunden skal oplyse Databehandleren om særlige risici, der har betydning for sikkerheden eller den aftalte behandling."},{"type":"paragraph","text":"Kunden afgør anmodninger fra registrerede og behovet for anmeldelse, underretning, konsekvensanalyse og forudgående høring. Dette begrænser ikke Databehandlerens selvstændige forpligtelser efter aftalen og gældende ret."},{"type":"heading","text":"4. Dokumenterede instrukser"},{"type":"paragraph","text":"Databehandleren må kun behandle personoplysninger efter Kundens dokumenterede instrukser, herunder ved overførsler til tredjelande, medmindre EU-ret eller medlemsstatens nationale ret kræver anden behandling. Ved et sådant lovkrav underretter Databehandleren Kunden før behandlingen, medmindre lovgivningen forbyder underretningen af hensyn til vigtige samfundsinteresser."},{"type":"paragraph","text":"Instrukserne består af denne aftale, dens bilag og Kundens autoriserede valg af funktioner og indstillinger. Supplerende instrukser gives skriftligt til axel@embedbot.dk eller gennem en verificeret kontokanal. Databehandleren registrerer instrukserne og afklarer uklarheder eller modstridende krav med Kunden før udførelse."},{"type":"paragraph","text":"Databehandleren underretter straks Kunden, hvis en instruks efter Databehandlerens vurdering strider mod databeskyttelsesreglerne. Den berørte behandling sættes i bero under afklaringen, i det omfang dette kan ske uden at kompromittere datasikkerheden."},{"type":"paragraph","text":"Databehandleren må ikke anvende Kundens personoplysninger til egne salgsformål eller til træning af egne generelle AI-modeller eller aktivere leverandørdeling til generel modeltræning af disse oplysninger."},{"type":"heading","text":"5. Fortrolighed og adgang"},{"type":"paragraph","text":"Databehandleren sikrer, at kun autoriserede personer med et nødvendigt arbejdsbetinget behov har adgang til personoplysningerne. Personerne skal være underlagt en passende lovbestemt eller aftalt fortrolighedsforpligtelse og instrueret i sikker behandling."},{"type":"paragraph","text":"Adgang skal tildeles efter princippet om mindst mulig adgang, gennemgås regelmæssigt og fjernes, når behovet ophører. Tilsvarende krav skal sikres gennem aftaler med underdatabehandlere."},{"type":"heading","text":"6. Behandlingssikkerhed"},{"type":"paragraph","text":"Databehandleren gennemfører passende tekniske og organisatoriske foranstaltninger efter artikel 32 under hensyn til behandlingens karakter, omfang, sammenhæng, formål og risiko for de registrerede. Foranstaltningerne er beskrevet i bilag B."},{"type":"paragraph","text":"Databehandleren skal kunne opretholde fortrolighed, integritet, tilgængelighed og robusthed og kunne genoprette adgang til oplysningerne rettidigt efter en fysisk eller teknisk hændelse. Sikkerhedsforanstaltningernes effektivitet skal regelmæssigt kontrolleres og vurderes."},{"type":"paragraph","text":"Foranstaltningerne kan tilpasses den tekniske udvikling og risikoen. Ændringer må ikke reducere det beskyttelsesniveau, aftalen kræver."},{"type":"heading","text":"7. Underdatabehandlere"},{"type":"paragraph","text":"Kunden giver ved aftaleindgåelsen generel skriftlig godkendelse til de underdatabehandlere, som er identificeret og omfattet af det aftalte bilag C. Godkendelsen omfatter kun de beskrevne behandlingsaktiviteter og behandlingssteder."},{"type":"paragraph","text":"Databehandleren varsler tilføjelse eller udskiftning mindst 30 kalenderdage før ændringen til Kundens registrerede kontaktmail. Varslet skal give Kunden tilstrækkelig information til at vurdere ændringen og mulighed for en begrundet indsigelse inden ændringen."},{"type":"paragraph","text":"Ved indsigelse søger parterne en lovlig løsning. Den berørte nye behandling påbegyndes ikke for Kunden, mens indsigelsen er uafklaret. Kan der ikke findes en lovlig løsning, kan den berørte del af tjenesten bringes til ophør med tilbagelevering og sletning efter punkt 13."},{"type":"paragraph","text":"Databehandleren indgår skriftlige aftaler med underdatabehandlerne, som pålægger dem de samme relevante databeskyttelsesforpligtelser som denne aftale, og sikrer tilstrækkelige garantier for passende sikkerhed. Databehandleren forbliver fuldt ansvarlig over for Kunden for underdatabehandlernes opfyldelse af disse forpligtelser."},{"type":"paragraph","text":"Databehandleren stiller efter anmodning relevante aftaleoplysninger til rådighed for Kunden. Irrelevante forretningsoplysninger kan beskyttes, uden at det forhindrer kontrollen af databeskyttelsesforpligtelserne."},{"type":"heading","text":"8. Internationale overførsler"},{"type":"paragraph","text":"Overførsel til eller adgang fra et land uden for EU/EØS må kun ske efter Kundens dokumenterede instruks og i overensstemmelse med databeskyttelsesforordningens kapitel V."},{"type":"paragraph","text":"Før overførslen skal Databehandleren dokumentere modtager, land, formål og gældende overførselsgrundlag samt nødvendige vurderinger og supplerende foranstaltninger. Oplysningerne skal indgå i bilag C eller en skriftlig supplering, som Kunden godkender før den berørte behandling. En generel leverandørliste giver ikke i sig selv instruks til ubeskrevne overførsler."},{"type":"paragraph","text":"Databehandleren må ikke love udelukkende EU/EØS-behandling alene på baggrund af en valgt databaseregion. Supportadgang, AI-behandling og videreoverførsler skal indgå i vurderingen. Hvis et grundlag bortfalder, skal den berørte overførsel standses, indtil et lovligt grundlag er etableret."},{"type":"heading","text":"9. Registreredes rettigheder"},{"type":"paragraph","text":"Databehandleren bistår Kunden med passende tekniske og organisatoriske foranstaltninger til at besvare anmodninger om de registreredes rettigheder, under hensyn til behandlingens karakter."},{"type":"paragraph","text":"Databehandleren videresender uden unødig forsinkelse anmodninger vedrørende Kundens behandling til Kundens autoriserede kontakt. Databehandleren afgør ikke anmodningen uden Kundens instruks, medmindre gældende ret kræver det."},{"type":"paragraph","text":"Kunden kontrollerer anmoderens identitet og ret til oplysningerne før opslag, udlevering eller sletning. En e-mailadresse i en chat er ikke identitetsbevis. Databehandleren bistår med søgning, sikker eksport, rettelse, begrænsning og sletning. Manglende søgeresultater eller tekniske begrænsninger meddeles Kunden, så historiske kopier, aliaser og andre relevante oplysninger kan gennemgås."},{"type":"heading","text":"10. Brud på persondatasikkerheden"},{"type":"paragraph","text":"Databehandleren underretter Kunden uden unødig forsinkelse efter at være blevet bekendt med et brud på persondatasikkerheden vedrørende Kundens oplysninger."},{"type":"paragraph","text":"Underretningen skal, i det omfang oplysningerne er tilgængelige, beskrive bruddets karakter, kategorier og omtrentligt antal registrerede og berørte dataposter, sandsynlige konsekvenser, relevante kontaktoplysninger samt trufne eller foreslåede afværgeforanstaltninger."},{"type":"paragraph","text":"Manglende oplysninger gives løbende uden unødig yderligere forsinkelse. Underretning afventer ikke en afsluttet undersøgelse. Databehandleren bistår Kunden med undersøgelse, afværgning og nødvendig dokumentation til anmeldelse og underretning."},{"type":"heading","text":"11. Assistance ved sikkerhed og vurderinger"},{"type":"paragraph","text":"Databehandleren bistår Kunden med forpligtelserne efter artikel 32–36 under hensyn til behandlingens karakter og de oplysninger, der er tilgængelige for Databehandleren."},{"type":"paragraph","text":"Assistance omfatter relevante oplysninger om behandlingen, sikkerhedsforanstaltninger, modtagere, behandlingssteder og risici samt bistand ved konsekvensanalyse og eventuel forudgående høring. Praktiske rammer aftales uden at begrænse den lovpligtige assistance."},{"type":"heading","text":"12. Opbevaring"},{"type":"paragraph","text":"Oplysninger opbevares efter perioderne i bilag D og Kundens dokumenterede instrukser. Afvigelser skal være begrundede og registreres. En ændring gælder fremadrettet efter den aftalte instruks og genskaber ikke allerede slettede oplysninger."},{"type":"paragraph","text":"Kopierede samtaleudsnit må ikke bevare oplysninger ud over den relevante kortere slettefrist. Databehandleren sikrer, at sletning også omfatter tilknyttede kopier og relevante underdatabehandlere efter den aftalte sletteprocedure. Lovpligtige undtagelser skal afgrænses og dokumenteres."},{"type":"heading","text":"13. Returnering og sletning ved ophør"},{"type":"paragraph","text":"Ved tjenestens ophør tilbageleverer eller sletter Databehandleren efter Kundens valg de personoplysninger, der behandles på Kundens vegne, og sletter eksisterende kopier, medmindre EU-ret eller medlemsstatens nationale ret kræver fortsat opbevaring."},{"type":"paragraph","text":"Kunden kan vælge eksport før sletning. Afslutningsperioden er højst 30 kalenderdage fra ophørsdatoen, og Kunden kan instruere tidligere sletning. Behandling i perioden begrænses til nødvendig sikker opbevaring, tilbagelevering og sletning; almindelig chatbotbehandling og integrationer skal ophøre. Kortere løbende slettefrister fortsætter uændret."},{"type":"paragraph","text":"Databehandlerens egne backupkopier udfases senest efter den aftalte backupfrist på 30 dage fra backupkopiens oprettelse. De må ikke bruges til almindelig behandling efter sletteinstruksen. Ved gendannelse skal tidligere sletninger genudføres før normal drift genoptages."},{"type":"paragraph","text":"Lovpligtig opbevaring begrænses til det nødvendige, og Kunden orienteres om omfang, grundlag og periode, medmindre lovgivningen forbyder orienteringen. Underleverandørers sletteforhold skal håndteres efter punkt 7 og bilag C; en leverandørs generelle kontoophørsfrist er ikke en forlængelse af Kundens aftalte slettefrist."},{"type":"paragraph","text":"Databehandleren dokumenterer og bekræfter afslutningen over for Kunden med dato, omfang og eventuelle lovpligtige undtagelser. Kundens egne downloads, indbakker og oplysninger i Kundens webshop håndteres af Kunden."},{"type":"heading","text":"14. Dokumentation og kontrol"},{"type":"paragraph","text":"Databehandleren stiller alle nødvendige oplysninger til rådighed for at dokumentere opfyldelsen af artikel 28 og giver mulighed for og bidrager til revisioner og inspektioner foretaget af Kunden eller en revisor, som Kunden har bemyndiget."},{"type":"paragraph","text":"Dokumentationsgennemgang kan anvendes som første trin, når den er tilstrækkelig. Nødvendig revision og inspektion tilrettelægges med sikker adgang og beskyttelse af andre kunders oplysninger. Fortrolighed eller almindelige varslingsregler må ikke forhindre en effektiv kontrol, herunder ved sikkerhedsbrud, myndighedskrav eller konkret mistanke om manglende overholdelse."},{"type":"heading","text":"15. Kontakt og samarbejde"},{"type":"paragraph","text":"Databehandlerens kontakt for instrukser, rettighedsanmodninger og sikkerhedshændelser er Axel Bødker Frederiksen, axel@embedbot.dk, +45 91 55 12 50."},{"type":"paragraph","text":"Kunden holder sine autoriserede kontaktoplysninger ajour. Databehandleren skal organisere modtagelse og håndtering af henvendelser, så aftalens forpligtelser også kan opfyldes ved fravær. Der aftales ikke en særskilt døgnbemandet supportordning eller fast reaktionstid; kravet om underretning uden unødig forsinkelse gælder fortsat."},{"type":"heading","text":"16. Rolleafgrænsning"},{"type":"paragraph","text":"Aftalen omfatter behandling på Kundens vegne. Behandling til Databehandlerens egne formål, eksempelvis administration af EmbedBot-abonnementer, fakturering og egne websitebesøg, beskrives særskilt i EmbedBots privatlivspolitik og omfattes ikke automatisk af Kundens instruks."},{"type":"paragraph","text":"Denne afgrænsning giver ikke Databehandleren ret til at genbruge Kundens chat-, lead- eller supportoplysninger til egne formål."},{"type":"heading","text":"17. Aftaleindgåelse og ændringer"},{"type":"paragraph","text":"Aftalen indgås ved dokumenteret accept af den publicerede version af en person med ret til at handle på Kundens vegne eller ved parternes skriftlige underskrift. Kundens identitet, aftaleversion, bilag og accepttidspunkt skal fremgå af aftaleregistreringen."},{"type":"paragraph","text":"Tidligere kunders brug udgør ikke accept af en ny version. Ændringer dokumenteres i en ny version, og tidligere aftaleversioner bevares. Aftalen må ikke fortolkes, så den begrænser rettigheder eller forpligtelser efter databeskyttelsesreglerne."},{"type":"heading","text":"Bilag A — behandling og instrukser"},{"type":"table","rows":[["Område","Aftalt behandling"],["Formål","Besvarelse af spørgsmål, kundeservice, videnssøgning og de support-/webshopfunktioner, Kunden har aktiveret. Leadopfølgning sker alene til Kundens dokumenterede lovlige formål."],["Behandlingshandlinger","Modtagelse, lagring, organisering, søgning, AI-generering, visning, eksport, videresendelse efter instruks og sletning."],["Registrerede","Kundens websitebesøgende, kunder, medarbejdere og andre personer, hvis oplysninger indgår i Kundens lovligt indlæste materiale eller henvendelser."],["Oplysninger","Chatindhold, frivillige kontaktoplysninger, tidspunkt, sideadresse, supportbeskrivelse og relevante samtaleudsnit. Videnskilder kan indeholde personoplysninger. Ved aktiv webshopintegration desuden ordre-reference, e-mail og begrænsede ordre-/statusoplysninger."],["AI","Relevante videnskilder, den aktuelle chat og nødvendig historik behandles hos den aftalte AI-leverandør til svar og embeddings. Personoplysninger, som indtastes i fri chattekst, kan indgå. Private ordreformularer og ordresvar følger særskilt verifikation."],["Leads","Dashboardet kan vise kontakt-e-mails fra chats med beskedudsnit, sideadresse og tidspunkt samt eksportere dem. Funktionen registrerer ikke marketingtilladelse. En kontakt-e-mail er ikke i sig selv samtykke til elektronisk markedsføring; Kunden sikrer nødvendig tilladelse eller gældende undtagelse."],["Særlige kategorier","Tjenesten er ikke indrettet til tilsigtet behandling af følsomme oplysninger eller oplysninger om strafbare forhold. Sådan planlagt behandling kræver særskilt skriftlig aftale, risikovurdering og passende foranstaltninger før påbegyndelse. Utilsigtet indtastning håndteres efter Kundens instruks."],["Kundevalgte modtagere","Kundens tilsluttede Shopify/WooCommerce-webshop og registrerede supportindbakke ved de valgte funktioner. Kundens egne eksporter og videresendelser håndteres under Kundens ansvar."]]},{"type":"paragraph","text":"Kundens konkrete funktioner, formål med leadopfølgning og eventuelle afvigende instrukser skal dokumenteres ved aftaleindgåelsen. Nye formål kræver en supplerende dokumenteret instruks."},{"type":"heading","text":"Bilag B — sikkerhedsforanstaltninger"},{"type":"paragraph","text":"Databehandleren skal opretholde følgende foranstaltninger i den behandling, aftalen omfatter:"},{"type":"list","items":["Serverkontrolleret login og ejerskab samt adskillelse af kundernes data i API''er og databaseadgang.","Begrænset adgang til private integrations- og compliancefunktioner; autorisation og passende flerfaktorbeskyttelse for privilegeret adgang.","Krypteret transport og beskyttelse af database og backup efter risikoen. Webshopcredentials og private ordrelokatorer beskyttes med autentificeret kryptering; nøgler holdes adskilt fra almindelige kundedata og udelades fra eksport.","Tidsbegrænset og sessionsbundet verifikation ved private ordreopslag, begrænsning af gentagne forsøg og kontrol af anmodningers oprindelse ved private ændringer.","Eksport af afgrænsede kundedata uden adgangskoder, API-nøgler, tokens eller integrationscredentials. Identitetskontrol og særskilt bekræftelse før besøgsdatasletning.","Begrænsede audit- og driftsoplysninger til dokumentation af handlinger og jobstatus uden unødvendigt chatindhold eller hemmeligheder.","Dokumenteret oprydning efter aftalte perioder, kontrol af udfald og håndtering af fejlede jobs.","Krypteret backup, beskyttet nøgleforvaring, rotation efter bilag D og regelmæssig kontrol af gendannelse, herunder håndtering af tidligere sletninger.","Vedligeholdelse, adgangsreview, fortrolighed, relevant oplæring og dokumenteret håndtering af sikkerhedshændelser og rettighedsanmodninger."]},{"type":"paragraph","text":"Foranstaltningerne beskriver Databehandlerens kontraktlige minimumsforpligtelser; de udgør ikke en certificering eller garanti for, at sikkerhedshændelser aldrig kan indtræffe."},{"type":"heading","text":"Bilag C — underdatabehandlere og behandlingssteder"},{"type":"paragraph","text":"Følgende leverandører indgår i tjenestens leverandørgrundlag. Anvendelse på Kundens vegne forudsætter, at de relevante aftaler og den konkrete overførselsinstruks efter punkt 8 er etableret før behandlingen."},{"type":"table","rows":[["Leverandør og juridisk enhed","Funktion og oplysninger","Behandlingssted og ramme"],["Supabase Pte. Ltd.","Database og kontologin; chats, supportsager, videnskilder, virksomhedsoplysninger og krypterede integrationer.","Projektets database og Auth ligger i Frankfurt, Tyskland. Supabases DPA indeholder SCC for relevante tredjelandsoverførsler. Supportadgang og videreoverførsler følger leverandørens DPA og underdatabehandlerliste og skal indgå i den konkrete overførselsvurdering."],["OpenAI Ireland Ltd. efter standardaftalen for EØS-kunder","API-svar, klassifikation og embeddings med relevant chat- og kildeindhold.","Det almindelige API anvendes uden en aftalt EU-behandlingsgaranti. OpenAIs DPA beskriver SCC eller en tilstrækkelighedsafgørelse ved relevante EØS-overførsler. Modtagere og supplerende foranstaltninger dokumenteres efter punkt 8."],["Plus Five Five, Inc. (Resend)","Transaktionsmail, supportnotifikationer og verifikationskoder ved de aktiverede funktioner.","Maildata lagres i USA; afsenderregionen Irland ændrer ikke lagringsstedet. Resends DPA indeholder SCC-modul 3 ved underdatabehandling. EmbedBots afsenderdomæne bruger Enforced TLS. Modtagerens egen indbakke styres af Kunden."],["Vercel Inc.","Hosting, serverbehandling og planlagte driftsjobs.","Vercels offentlige DPA beskriver primær behandling i USA og SCC for relevante overførsler og gælder Pro/Enterprise. EmbedBot bruger Hobby; dækkende kommerciel hosting og databehandleraftale skal etableres før kundeaccept. Den generelle DPA registreres ikke som gældende for Hobby."]]},{"type":"paragraph","text":"Før Kundens behandling påbegyndes, skal den kundespecifikke supplering identificere følgende for hver relevant overførsel: juridisk modtager, land, behandlingsaktivitet, datakategorier, adgangsform, overførselsgrundlag og nødvendige supplerende foranstaltninger. Manglende supplering giver ingen tilladelse til den ubeskrevne overførsel."},{"type":"paragraph","text":"Leverandørers særskilte sikkerheds-, log- og backupkopier skal kortlægges og indgå i den konkrete sletteprocedure. Almindelig OpenAI abuse-monitoring kan indebære opbevaring i op til 30 dage med leverandørens beskrevne undtagelser. Resend beskriver 30 dages mail-/logopbevaring, syv dages backup og en særskilt frist efter lukning af hele leverandørkontoen. Lukning af hele leverandørkontoen er ikke det samme som ophør for én Kunde. Sådanne generelle leverandørvilkår udgør hverken en slettebekræftelse for Kundens oplysninger eller en selvstændig tilladelse til længere opbevaring efter denne aftale."},{"type":"paragraph","text":"Kundens egen webshop, supportindbakke og eksporter er kundevalgte datakilder og modtagere. Stripe-betaling for EmbedBots abonnementer og analyse af EmbedBots eget website omfattes ikke automatisk af dette underdatabehandlerbilag."},{"type":"heading","text":"Bilag D — opbevaring, eksport og ophør"},{"type":"table","rows":[["Oplysninger eller handling","Instruks"],["Chats og afledte leads i EmbedBot","30 dage fra samtalens oprettelse, medmindre en begrundet anden periode er dokumenteret. Leads følger samtalens sletning."],["Supportsager","90 dage fra supportsagens oprettelse, medmindre en begrundet anden periode er dokumenteret."],["Kopieret chatkontekst","Den relevante kortere chat-/sagsfrist; skal også fjernes ved sletning af den tilknyttede samtale."],["Videnskilder og integrationsdata","Så længe de er nødvendige for den aftalte aktive tjeneste; fjernes ved relevant udskiftning, frakobling eller ophør efter instruks."],["Midlertidige verifikations- og forbindelsesoplysninger","Efter deres tekniske udløb, når de ikke længere er nødvendige for det afgrænsede sikkerhedsformål."],["Databehandlerens egne databasebackups","Højst 30 dage fra den enkelte backupkopis oprettelse; tidligere sletninger respekteres ved gendannelse."],["Eksport og sletning ved ophør","Efter Kundens valg, afsluttet senest 30 kalenderdage fra tjenestens ophør eller tidligere efter Kundens instruks."],["Kundevalgte kopier","Kundens downloads, indbakker og webshopoplysninger håndteres og slettes af Kunden."]]},{"type":"paragraph","text":"Perioderne er kontraktlige instrukser og ikke generelle lovbestemte standardfrister. Kunde- eller formålsspecifikke afvigelser registreres med begrundelse og autoriseret instruks. Opbevaring af interne sikkerheds-/auditoplysninger skal afgrænses efter deres eget nødvendige formål; sådanne logs må ikke bruges til at bevare slettet chatindhold eller credentials."}],"sources":[{"label":"Supabase — aftale og behandling","url":"https://supabase.com/legal/customer-resources/data-processing-addendum"},{"label":"OpenAI — aftale og behandling","url":"https://openai.com/policies/data-processing-addendum/"},{"label":"Vercel — aftale og behandling","url":"https://vercel.com/legal/dpa"},{"label":"Resend — aftale og behandling","url":"https://resend.com/legal/dpa"}],"sha256":"53dfc2e1bc2037df8e36a520aba61cc33b3f84ceb8df8a3ea31ba0a6c3e0fb67"}'::jsonb);
commit;
